mapper.select:
SELECT * FROM rec_talent_pool

    deleted = 0

        AND pool_type = #{params.poolType}


        AND skill_level = #{params.skillLevel}


        AND availability = #{params.availability}


        AND (
            expected_position LIKE CONCAT('%', #{params.keyword}, '%')
            OR JSON_SEARCH(tags, 'one', CONCAT('%', #{params.keyword}, '%')) IS NOT NULL
        )


ORDER BY create_time DESC
